/**
 * Converts an array of Gemini {@link Part}s into the internal
 * {@link ContentPart} representation.
 *
 * - `text` parts become `{ type: 'text' }`.
 * - `thought` parts become `{ type: 'thought' }`, carrying `thoughtSignature`
 *   when present.
 * - `inlineData` parts become `{ type: 'media' }`, preserving `data` and
 *   `mimeType`.
 * - `fileData` parts become `{ type: 'media' }`, mapping `fileUri` to `uri` and
 *   preserving `mimeType`.
 * - `functionCall` and `functionResponse` parts are skipped.
 * - Unknown parts are serialized to a `{ type: 'text' }` part containing the
 *   JSON-stringified part, tagged as unknown via `_meta`.
 */
export function geminiPartsToContentParts(parts: Part[]): ContentPart[] {
  const result: ContentPart[] = [];

  for (const part of parts) {
    // Thought parts are text parts flagged with `thought: true`; check them
    // before plain text so they are not misclassified.
    if (part.thought) {
      const contentPart: ContentPart = {
        type: 'thought',
        thought: part.text ?? '',
      };
      if (part.thoughtSignature !== undefined) {
        contentPart.thoughtSignature = part.thoughtSignature;
      }
      result.push(contentPart);
      continue;
    }

    if (part.text !== undefined) {
      result.push({ type: 'text', text: part.text });
      continue;
    }

    if (part.inlineData) {
      result.push({
        type: 'media',
        data: part.inlineData.data,
        mimeType: part.inlineData.mimeType,
      });
      continue;
    }

    if (part.fileData) {
      result.push({
        type: 'media',
        uri: part.fileData.fileUri,
        mimeType: part.fileData.mimeType,
      });
      continue;
    }

    // Function-call and function-response parts are handled elsewhere.
    if (part.functionCall || part.functionResponse) {
      continue;
    }

    // Unknown part type: preserve it as serialized text so nothing is lost.
    result.push({
      type: 'text',
      text: JSON.stringify(part),
      _meta: { unknown: true },
    });
  }

  return result;
}

/**
 * Converts internal {@link ContentPart}s back into Gemini {@link Part}s.
 *
 * - `text` parts become `{ text }`.
 * - `thought` parts become `{ text, thought: true }`, carrying
 *   `thoughtSignature` when present.
 * - `media` parts with `data` become `inlineData` parts, defaulting `mimeType`
 *   to `application/octet-stream`.
 * - `media` parts with `uri` become `fileData` parts.
 * - `media` parts with neither `data` nor `uri` are skipped.
 * - Unknown part variants are serialized to a `{ text }` part containing the
 *   JSON-stringified content.
 */
export function contentPartsToGeminiParts(parts: ContentPart[]): Part[] {
  const result: Part[] = [];

  for (const part of parts) {
    switch (part.type) {
      case 'text':
        result.push({ text: part.text });
        break;

      case 'thought': {
        const geminiPart: Part = { text: part.thought, thought: true };
        if (part.thoughtSignature !== undefined) {
          geminiPart.thoughtSignature = part.thoughtSignature;
        }
        result.push(geminiPart);
        break;
      }

      case 'media':
        if (part.data !== undefined) {
          result.push({
            inlineData: {
              data: part.data,
              mimeType: part.mimeType ?? 'application/octet-stream',
            },
          });
        } else if (part.uri !== undefined) {
          result.push({
            fileData: {
              fileUri: part.uri,
              mimeType: part.mimeType,
            },
          });
        }
        // Media without data or uri carries nothing to send; skip it.
        break;

      default:
        // Unknown variant: preserve it as serialized text.
        result.push({ text: JSON.stringify(part) });
        break;
    }
  }

  return result;
}

/**
 * Normalizes a tool result's display value into {@link ContentPart}s.
 *
 * - `undefined`/`null` yields `undefined`.
 * - Strings yield a single text part.
 * - Any other value is JSON-stringified into a single text part.
 */
export function toolResultDisplayToContentParts(
  value: unknown,
): ContentPart[] | undefined {
  if (value === undefined || value === null) {
    return undefined;
  }

  if (typeof value === 'string') {
    return [{ type: 'text', text: value }];
  }

  return [{ type: 'text', text: JSON.stringify(value) }];
}

/** Recognized fields used to build a tool response's structured data. */
export interface ToolResponseDataInput {
  errorType?: string;
  outputFile?: string;
  contentLength?: number;
  data?: Record<string, unknown>;
}

/**
 * Builds the structured `data` payload for a tool response from a set of
 * recognized fields.
 *
 * Returns `undefined` when none of the recognized fields are present.
 * Otherwise includes `errorType`, `outputFile`, and `contentLength` when set,
 * and merges any provided `data` object into the top-level result.
 */
export function buildToolResponseData(
  input: ToolResponseDataInput,
): Record<string, unknown> | undefined {
  const { errorType, outputFile, contentLength, data } = input;

  if (
    errorType === undefined &&
    outputFile === undefined &&
    contentLength === undefined &&
    data === undefined
  ) {
    return undefined;
  }

  const result: Record<string, unknown> = {};

  if (errorType !== undefined) {
    result['errorType'] = errorType;
  }
  if (outputFile !== undefined) {
    result['outputFile'] = outputFile;
  }
  if (contentLength !== undefined) {
    result['contentLength'] = contentLength;
  }
  if (data !== undefined) {
    Object.assign(result, data);
  }

  return result;
}
